def is_pal(s):
    for i in range(len(s) // 2):
        if s[i] != s[len(s) - 1 - i]:
            return False
    return True

def caesar(s, k):
    r = ""
    for ch in s:
        r += chr((ord(ch) - ord("a") + k) % 26 + ord("a"))
    return r

print(is_pal("racecar"), is_pal("braude"))
print(caesar("xyz", 3), caesar("hello", 1))

